style.css:
@-moz-document domain("discord.com") {
:root, .theme-dark, .theme-light {
        /* Fundos Principais */
        --background-primary: #FFF0F3 !important;      /* Fundo do chat principal */
        --background-secondary: #FFCCD5 !important;    /* Barra lateral de canais */
        --background-secondary-alt: #FFB3C1 !important;/* Caixa do seu perfil no canto */
        --background-tertiary: #FFB3C1 !important;     /* Barra com a lista de servidores */
        --background-floating: #FFF0F3 !important;     /* Menus que abrem por cima */
        
        /* Caixas de Texto e Mensagens */
        --channeltextarea-background: #FFFFFF !important; /* Caixa onde você digita */
        --background-message-hover: rgba(255, 255, 255, 0.4) !important; /* Efeito ao passar o mouse */
        
        /* Cores de Texto (Marrom suave para contraste confortável) */
        --text-normal: #5C4B49 !important;             /* Texto das mensagens */
        --text-muted: #8A7371 !important;              /* Textos secundários/data */
        --header-primary: #4A3A38 !important;          /* Nomes dos canais e títulos */
        --header-secondary: #5C4B49 !important;
        --channels-default: #6F5A57 !important;         /* Canais não lidos/padrão */
        
        /* Detalhes e Botões */
        --brand-experiment: #FF758F !important;        /* Botões principais e links (Rosa Atrevido) */
        --brand-experiment-560: #FF4D6D !important;    /* Botão de enviar/interagir */
        --interactive-normal: #5C4B49 !important;      /* Ícones normais */
        --interactive-hover: #FF4D6D !important;       /* Ícones quando passa o mouse */
        --interactive-active: #FFFFFF !important;      /* Ícones ativos */
        
        /* Modificadores de Estado */
        --background-modifier-hover: rgba(255, 255, 255, 0.3) !important;
        --background-modifier-selected: rgba(255, 255, 255, 0.6) !important;
    }

    /* Ajustes para deixar o design mais suave e arredondado (cozy) */
    div[class*="messageInput_"], div[class*="inner_"] {
        border-radius: 12px !important;
        border: 1px solid #FF758F !important;
    }

    div[class*="sidebar_"] {
        border-right: 1px solid rgba(255, 117, 143, 0.2) !important;
    }

    div[class*="member_"] {
        border-radius: 8px !important;
        margin: 2px 8px !important;
    }
}
